    public record EnvelopeV4(String format,int version,UUID storeId,long storeRevision,Instant writtenAt,String checksumAlgorithm,String checksum,JsonNode data){}
    private record EnvelopeNode(String format,int version,UUID storeId,long storeRevision,Instant writtenAt,String checksumAlgorithm,String checksum,JsonNode data){}
    private record VersionProbe(String format,int version){} private record Candidate(Path path,RecoverySource source,State state,long revision,UUID storeId,byte[] bytes,boolean legacy){}
